(function(E){ const x = E["int-m1"] = E["int-m1"] || {units:{}}; x.units["int-10"] = {"grammar":{"id":"c-int-10-g","level":"B1","course":"interview","unit":"int-10","title":"CV lines: verb first, then the result","titleTr":"CV satırları: önce fiil, sonra sonuç","titleFa":"خط‌های رزومه: اول فعل، بعد نتیجه","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Start with the verb, no I","Trained 12 new staff."],["Finished result: past simple","Cut delivery time by two days."],["A duty you still do: present simple","Answer about 60 emails a day."],["How much: by + number","Increased sales by 20%."],["Numbers in English","20% (not %20), 1,500 (not 1.500)"]]},"wrong":"Increased online sales %25 in one year.","right":"Increased online sales by 25% in one year.","blank":{"sentence":"___ a new booking system in 2024, which cut phone calls by 30%.","word":"Introduced","distractors":["Introduce","Introduces"]},"wrong2":"I am answering about 60 customer emails a day.","right2":"Answer about 60 customer emails a day.","blank2":{"sentence":"Reduced customer complaints ___ 15% in six months.","word":"by","distractors":["with","of"]},"expParts":{"rule":[{"en":"Start with the verb and leave out I, because the whole CV is about you.","tr":"Fiille başla ve I yazma, çünkü CV'nin tamamı zaten seninle ilgili.","fa":"خط را با فعل شروع کن و I را ننویس، چون کل رزومه درباره‌ی خودت است.","ex":"Trained 12 new staff."},{"en":"Use the past simple for finished results, and the present simple for duties you still do.","tr":"Bitmiş sonuçlar için past simple, hâlâ yaptığın görevler için present simple kullan.","fa":"برای نتیجه‌ای که تمام شده گذشته‌ی ساده بیاور و برای کاری که هنوز انجام می‌دهی حال ساده.","ex":"Cut costs by 10%. Answer 60 emails a day."},{"en":"Give the size of a change with by + number. Write 20%, not %20.","tr":"Değişimin miktarını by + sayı ile ver. %20 değil, 20% yaz.","fa":"مقدار تغییر را با by و یک عدد بگو، و بنویس 20%، نه %20.","ex":"Increased sales by 20%."}],"test":{"en":"Is it a CV line? Start with the verb. Is it finished? Use the past.","tr":"CV satırı mı? Fiille başla. Bitmiş mi? Geçmiş zaman kullan.","fa":"خط رزومه است؟ با فعل شروعش کن. تمام شده؟ گذشته بیاور."},"contrast":{"en":"Turkish writes %20 and 1.500; English writes 20% and 1,500. Turkish and Persian CVs often open lines with 'sorumlu' or 'مسئول'; in English, open with the action.","tr":"Türkçede %20 ve 1.500 yazılır; İngilizcede 20% ve 1,500. Türkçe CV'lerde satırlar çoğu zaman 'sorumlu' ile başlar; İngilizcede yaptığın işle başla: Trained, Cut.","fa":"در انگلیسی علامت درصد بعد از عدد می‌آید (20%) و هزارگان را با ویرگول جدا می‌کنند (1,500). در رزومه‌ی فارسی خیلی از خط‌ها با «مسئول» شروع می‌شوند؛ در انگلیسی خط را با کاری که کردی شروع کن: Trained، Cut."}},"errorWatch":[{"find":["%5","%10","%15","%20","%25","%30","%40","%50","%60","%70","%80","%90","%100"],"fix":{"en":"In English the number comes first: 20%, not %20.","tr":"İngilizcede sayı önce gelir: %20 değil, 20%.","fa":"در انگلیسی اول عدد می‌آید: 20%، نه %20."}},{"find":["responsible of","responsible from","increased with","reduced with","decreased with","grew with"],"fix":{"en":"Say 'responsible for', and use 'by' for the size of a change: 'Increased sales by 20%.'","tr":"'responsible for' de; değişimin miktarı için 'by' kullan: 'Increased sales by 20%.'","fa":"بگو «responsible for» و برای مقدار تغییر by بیاور: «Increased sales by 20%.»"}}]},"b2":{"id":"c-int-10-b2","level":"B2","track":"B2","course":"interview","unit":"int-10","title":"How you did it: by + -ing, from ... to","titleTr":"Nasıl yaptığın: by + -ing, from ... to","titleFa":"چطور انجامش دادی: by + ‎-ing و from ... to","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["How: by + -ing","Cut costs by switching suppliers."],["How first, for focus","By introducing online booking, cut calls by 30%."],["The change: from ... to ...","Reduced delivery time from five days to two."]]},"wrong":"Cut costs by switch suppliers.","right":"Cut costs by switching suppliers.","blank":{"sentence":"Saved two hours a week by ___ the monthly reports.","word":"automating","distractors":["automate","automated"]},"wrong2":"Reduced delivery time five days to two.","right2":"Reduced delivery time from five days to two.","blank2":{"sentence":"Cut waiting time ___ 20 minutes to 8.","word":"from","distractors":["since","of"]},"useIn":{"en":"B2: in your writing, add one line that says how, with by + -ing, or shows a change with from ... to.","tr":"B2: yazına, nasıl yaptığını by + -ing ile anlatan ya da from ... to ile bir değişimi gösteren bir satır ekle.","fa":"در مسیر B2: در نوشته‌ات یک خط اضافه کن که با by + ‎-ing بگوید چطور انجامش دادی، یا با from ... to تغییر را نشان بدهد."},"exitItem":{"from":"int-10","kind":"blank","prompt":"___ a shared calendar, the team stopped double bookings.","options":["By introducing","By introduce","With introducing"],"correct":0,"why":{"en":"By introducing: by + -ing says how you did it. 'By introduce' needs -ing, and 'with introducing' is not English here.","tr":"By introducing: by + -ing nasıl yaptığını söyler. 'By introduce' -ing ister; 'with introducing' burada İngilizce değildir.","fa":"By introducing درست است، چون by و فعل ing‌دار می‌گوید چطور انجامش دادی. by introduce باید ‎-ing بگیرد و with introducing اینجا انگلیسی نیست."}},"expParts":{"rule":[{"en":"Say how you did it: by + -ing.","tr":"Nasıl yaptığını söyle: by + -ing.","fa":"برای اینکه بگویی چطور انجامش دادی، by و فعل ing‌دار بیاور.","ex":"Cut costs by switching suppliers."},{"en":"Put how first when it is the strong part: By + -ing, then the result.","tr":"Güçlü kısım yöntemse onu başa al: By + -ing, sonra sonuç.","fa":"اگر نقطه‌ی قوت همان روش است، اول بیاورش: By + ‎-ing و بعد نتیجه.","ex":"By introducing online booking, cut calls by 30%."},{"en":"Show the change with from ... to.","tr":"Değişimi from ... to ile göster.","fa":"تغییر را با from ... to نشان بده.","ex":"Reduced delivery time from five days to two."}],"test":{"en":"Is there a verb after by? Add -ing.","tr":"by'dan sonra fiil mi var? -ing ekle.","fa":"بعد از by فعل آمده؟ ‎-ing اضافه کن."},"contrast":{"en":"Turkish '-erek' and Persian 'با عوض کردن' put 'how' inside the verb, so learners write 'by switch'. English needs by + -ing.","tr":"Türkçedeki '-erek' nasıl yapıldığını fiilin içinde verir; bu yüzden 'by switch' yazılır. İngilizce by + -ing ister: by switching.","fa":"در فارسی «با عوض کردن تأمین‌کننده» روش را با مصدر می‌گوییم؛ برای همین «by switch» می‌نویسیم. انگلیسی by و فعل ing‌دار می‌خواهد: by switching."}},"errorWatch":[{"find":["by switch","by introduce","by automate","by create","by reduce","by improve"],"fix":{"en":"After by, use -ing: 'by switching', 'by introducing'.","tr":"by'dan sonra -ing kullan: 'by switching', 'by introducing'.","fa":"بعد از by فعل ing‌دار بیاور: «by switching»، «by introducing»."}}]},"vocab":{"id":"c-int-10-v","level":"B1","category":"vocab","course":"interview","unit":"int-10","goals":["career"],"title":{"en":"CVs and Cover Letters","tr":"CV ve Ön Yazı","fa":"رزومه و کاور لتر"},"cards":[{"word":"CV","sentence":"Please send your CV and a short cover letter.","meaning":{"en":"A short document about your work, education and skills. In the US it is a résumé.","tr":"özgeçmiş (CV); ABD'de résumé denir.","fa":"رزومه؛ در آمریکا به آن résumé می‌گویند."}},{"word":"cover letter","sentence":"The cover letter says why you want this job.","meaning":{"en":"A short letter you send with your CV.","tr":"ön yazı; CV ile gönderilen kısa mektup.","fa":"کاور لتر؛ نامه‌ی کوتاهی که همراه رزومه می‌فرستی."}},{"word":"profile","sentence":"Start your CV with a three-line profile.","meaning":{"en":"Here: a short summary at the top of a CV.","tr":"burada: CV'nin başındaki kısa özet.","fa":"اینجا: خلاصه‌ی کوتاه بالای رزومه."}},{"word":"achievement","sentence":"Each line should show an achievement, not just a duty.","meaning":{"en":"Something good you did, with a result.","tr":"başarı; sonucu olan iyi bir iş.","fa":"دستاورد؛ کار خوبی که نتیجه داشته."}},{"word":"duty","sentence":"Answering the phone was one of my duties.","meaning":{"en":"A task that is part of your job.","tr":"görev.","fa":"وظیفه."},"gap":"duties","accept":["duties"]},{"word":"tailor","sentence":"You should tailor your CV to each job ad.","meaning":{"en":"To change something so it fits one purpose.","tr":"bir amaca göre uyarlamak.","fa":"چیزی را برای یک هدف مشخص تنظیم کردن."}},{"word":"keyword","sentence":"Use the keywords from the job ad in your CV.","meaning":{"en":"An important word that a reader or a computer looks for.","tr":"anahtar kelime.","fa":"کلیدواژه."},"gap":"keywords","accept":["keywords"]},{"word":"hiring manager","sentence":"Address the letter to the hiring manager by name.","meaning":{"en":"The person who decides who gets the job.","tr":"işe alım kararını veren yönetici.","fa":"مدیری که درباره‌ی استخدام تصمیم می‌گیرد."}},{"word":"shortlist","sentence":"Only six people were shortlisted for an interview.","meaning":{"en":"To choose a small group from all the people who applied.","tr":"kısa listeye almak; başvuranlar arasından az kişiyi seçmek.","fa":"در فهرست نهایی گذاشتن؛ انتخاب چند نفر از میان همه‌ی متقاضی‌ها."},"gap":"shortlisted","accept":["shortlisted"]},{"word":"reference","sentence":"Ask before you give someone's name as a reference.","meaning":{"en":"Here: a person who can tell an employer about your work.","tr":"burada: işini işverene anlatabilecek referans kişi.","fa":"اینجا: معرف؛ کسی که می‌تواند درباره‌ی کارت به کارفرما توضیح بدهد."}}]},"judge":{"id":"c-int-10-j","course":"interview","unit":"int-10","type":"judge","title":{"en":"Which CV line works?","tr":"Hangi CV satırı işe yarar?","fa":"کدام خط رزومه کار می‌کند؟"},"prompt":"The ad: Customer Support Assistant at an online shop. Answer customer emails and calls in English, and solve complaints. Five candidates sent one CV line each.","parts":["Starts with an action","Shows a result","Matches the ad"],"instruction":{"en":"Tap what each line does. The strongest line does all three.","tr":"Her satırın ne yaptığına dokun. En güçlü satır üçünü de yapar.","fa":"روی کاری که هر خط می‌کند بزن. قوی‌ترین خط هر سه را انجام می‌دهد."},"items":[{"by":"Graduate","answer":"Hard-working, friendly team player with excellent communication skills.","present":[],"fix":{"en":"Anyone can write this, so it proves nothing. Show one thing you did: 'Answered about 40 student emails a week in English.'","tr":"Bunu herkes yazabilir, bu yüzden hiçbir şey kanıtlamaz. Yaptığın bir şeyi göster: 'Answered about 40 student emails a week in English.'","fa":"این را هر کسی می‌تواند بنویسد، پس چیزی را ثابت نمی‌کند. یک کار واقعی‌ات را نشان بده: «Answered about 40 student emails a week in English.»"}},{"by":"Accountant","answer":"Responsible for monthly reports and supplier payments.","present":[],"fix":{"en":"'Responsible for' names a desk, not an action, and this ad is about customers. Choose a line about people: 'Solved supplier questions by phone, about 20 a week.'","tr":"'Responsible for' bir eylemi değil, bir masayı anlatır; bu ilan da müşterilerle ilgili. İnsanlarla ilgili bir satır seç: 'Solved supplier questions by phone, about 20 a week.'","fa":"«Responsible for» از یک جایگاه حرف می‌زند، نه از یک کار، و این آگهی درباره‌ی مشتری است. خطی درباره‌ی آدم‌ها انتخاب کن: «Solved supplier questions by phone, about 20 a week.»"}},{"by":"Sales assistant","answer":"Answered customer calls and emails in English.","present":["Starts with an action","Matches the ad"],"fix":{"en":"Right verb and right skill. Now show the result: 'Answered 70 calls a day in English, with 92% positive feedback.'","tr":"Fiil de beceri de doğru. Şimdi sonucu göster: 'Answered 70 calls a day in English, with 92% positive feedback.'","fa":"فعل درست است و مهارت هم همان است که آگهی می‌خواهد. حالا نتیجه را نشان بده: «Answered 70 calls a day in English, with 92% positive feedback.»"}},{"by":"Receptionist","answer":"Cut the hotel's check-in time from 10 minutes to 4.","present":["Starts with an action","Shows a result"],"fix":{"en":"A real result, but this ad wants emails, calls and complaints. Put the matching line first: 'Solved guest complaints in English, most on the same day.'","tr":"Gerçek bir sonuç, ama bu ilan e-posta, telefon ve şikâyet istiyor. İlana uyan satırı başa koy: 'Solved guest complaints in English, most on the same day.'","fa":"نتیجه‌ی واقعی است، ولی این آگهی ایمیل، تلفن و رسیدگی به شکایت می‌خواهد. خطی را که با آگهی جور است اول بیاور: «Solved guest complaints in English, most on the same day.»"}},{"by":"Good model","answer":"Solved about 15 customer complaints a day by email and phone in English, with 95% positive feedback.","present":["Starts with an action","Shows a result","Matches the ad"],"fix":null}]},"speaking":{"id":"int-10","course":"interview","unit":"int-10","topic":{"en":"Talk me through your CV","tr":"CV'ni bana anlat","fa":"رزومه‌ات را برایم توضیح بده"},"warmup":{"en":"Open your CV, or write three lines about your last job. Read the first line aloud.","tr":"CV'ni aç ya da son işinle ilgili üç satır yaz. İlk satırı yüksek sesle oku.","fa":"رزومه‌ات را باز کن، یا سه خط درباره‌ی آخرین کارت بنویس. خط اول را بلند بخوان."},"questions":[{"en":"\"Talk me through your CV.\" Start with your current or last job, in two sentences.","tr":"\"Talk me through your CV.\" İki cümleyle şu anki ya da son işinden başla.","fa":"«Talk me through your CV.» با کار فعلی یا آخرین کارت شروع کن، در دو جمله."},{"en":"Choose one line on your CV. Say what you did and what changed, with a number.","tr":"CV'nden bir satır seç. Ne yaptığını ve neyin değiştiğini bir sayıyla söyle.","fa":"یک خط از رزومه‌ات را انتخاب کن. بگو چه کردی و چه چیزی تغییر کرد، با یک عدد."},{"en":"\"I see 'good with customers' here. Can you give me an example?\" Answer with one real example.","tr":"\"I see 'good with customers' here. Can you give me an example?\" Gerçek bir örnekle cevap ver.","fa":"«I see 'good with customers' here. Can you give me an example?» با یک نمونه‌ی واقعی جواب بده."},{"en":"The recruiter asks: \"Can you send me your CV in English today?\" Say yes, say when, and check their email address.","tr":"İşe alım uzmanı soruyor: \"Can you send me your CV in English today?\" Evet de, ne zaman göndereceğini söyle ve e-posta adresini teyit et.","fa":"کارشناس استخدام می‌پرسد: «Can you send me your CV in English today?» بگو بله، بگو کی می‌فرستی و آدرس ایمیلش را دوباره بپرس."},{"en":"Finish: say in one sentence why your CV fits this job.","tr":"Bitir: CV'nin bu işe neden uyduğunu tek cümleyle söyle.","fa":"جمع‌بندی کن: در یک جمله بگو چرا رزومه‌ات به این کار می‌خورد."}],"followups":[{"en":"Do it again in 60 seconds, then 45. Keep your number in every round.","tr":"Önce 60, sonra 45 saniyede yeniden yap. Sayını her turda koru.","fa":"دوباره در ۶۰ و بعد ۴۵ ثانیه انجامش بده. عددت را در هر دور نگه دار."}],"expressions":[{"phrase":"In my current role, I...","meaning":{"en":"Starts with what you do now.","tr":"Şu anda ne yaptığınla başlar.","fa":"با کاری که الان می‌کنی شروع می‌کند."}},{"phrase":"As you can see on my CV, ...","meaning":{"en":"Points to a line they can read.","tr":"Okuyabilecekleri bir satırı gösterir.","fa":"به خطی اشاره می‌کند که خودشان می‌توانند بخوانند."}},{"phrase":"The result was...","meaning":{"en":"Brings in your number.","tr":"Sayını devreye sokar.","fa":"عددت را وارد حرفت می‌کند."}}],"selfCheck":[{"en":"I started with my current or last job.","tr":"Şu anki ya da son işimle başladım.","fa":"با کار فعلی یا آخرین کارم شروع کردم."},{"en":"I gave one line with a number.","tr":"Sayı içeren bir satır söyledim.","fa":"یک خط با عدد گفتم."},{"en":"I gave a real example, not just a skill word.","tr":"Sadece bir beceri kelimesi değil, gerçek bir örnek verdim.","fa":"یک نمونه‌ی واقعی گفتم، نه فقط اسم یک مهارت را."},{"en":"I linked my CV to this job at the end.","tr":"Sonunda CV'mi bu işe bağladım.","fa":"در آخر رزومه‌ام را به همین کار ربط دادم."}],"model":"Sure. In my current role, I work in the call centre of a bank in Izmir. I answer about 70 calls a day in English and Turkish. As you can see on my CV, I also solved customer complaints in a shop for two years. The result I'm proudest of is our score: 92% positive feedback last year. That's why I'm applying for this support role."},"writing":{"id":"c-int-10-w","course":"interview","unit":"int-10","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"int-final-8","model":"Dear Ms Ersoy,\n\nI am applying for the Customer Support Assistant role advertised on your website.\n\nI have worked in customer service for four years. In my current job at a bank call centre, I answer about 70 calls a day in English and Turkish, and our team has 92% positive feedback. Before that, I solved customer complaints in a busy shop.\n\nI would like to join your company because you sell to customers in many countries, and I enjoy solving problems in English. I would welcome the chance to discuss the role at an interview.\n\nYours sincerely,\nYour name","frame":"Dear ___,\n\nI am applying for the ___ role advertised on ___.\n\nI have worked in ___ for ___. In my current job, I ___, and ___. Before that, I ___.\n\nI would like to join your company because ___. I would welcome the chance to discuss the role at an interview.\n\nYours sincerely,\n___","words":[{"word":"applying for"},{"word":"I have worked"}],"minWords":90,"minSentences":5,"title":{"en":"Your cover letter","tr":"Ön yazın","fa":"کاور لتر تو"},"prompt":{"en":"Write a short cover letter (90-130 words) for this ad, or for your own: Customer Support Assistant at an online shop, English emails and calls, solving complaints. Paragraph 1: the job and where you saw it. Paragraph 2: two facts that match the ad. Paragraph 3: why this company, and ask for an interview.","tr":"Bu ilan ya da kendi ilanın için kısa bir ön yazı yaz (90-130 kelime): bir online mağazada Customer Support Assistant, İngilizce e-posta ve telefon, şikâyetleri çözmek. 1. paragraf: iş ve ilanı nerede gördüğün. 2. paragraf: ilana uyan iki bilgi. 3. paragraf: neden bu şirket ve mülakat isteği.","fa":"برای این آگهی یا آگهی خودت یک کاور لتر کوتاه بنویس (۹۰ تا ۱۳۰ کلمه): Customer Support Assistant در یک فروشگاه اینترنتی، ایمیل و تلفن به انگلیسی، حل شکایت‌ها. پاراگراف ۱: خود کار و جایی که آگهی را دیدی. پاراگراف ۲: دو واقعیت که با آگهی جورند. پاراگراف ۳: چرا این شرکت، و درخواست مصاحبه."},"rubric":["Task done: the job and where you saw it, two facts that match, why this company, a request for an interview","Organised: three short paragraphs: the job, the match, the close","Language: present perfect for your experience; past simple for finished results","Tone: confident and specific: no 'hard-working team player'"],"rubricI18n":{"tr":["Görev: iş ve ilanı nerede gördüğün, uyan iki bilgi, neden bu şirket, mülakat isteği","Düzen: üç kısa paragraf: iş, uyum, kapanış","Dil: deneyimin için present perfect; bitmiş sonuçlar için past simple","Üslup: kendinden emin ve somut: 'hard-working team player' yok"],"fa":["کامل بودن کار: خود کار و جایی که آگهی را دیدی، دو واقعیت جور با آگهی، چرا این شرکت، درخواست مصاحبه","نظم: سه پاراگراف کوتاه: خود کار، تطابق، پایان","زبان: حال کامل برای تجربه‌ات؛ گذشته‌ی ساده برای نتیجه‌های تمام‌شده","لحن: مطمئن و مشخص؛ بدون «hard-working team player»"]},"parts":[{"t":{"en":"The job and where you saw it","tr":"İş ve ilanı nerede gördüğün","fa":"خود کار و جایی که آگهی را دیدی"},"find":["applying for","advertised","your advert","job ad","on your website","on linkedin","i saw your","i saw the"]},{"t":{"en":"Two facts with numbers that match the ad","tr":"İlana uyan, sayı içeren iki bilgi","fa":"دو واقعیت با عدد که با آگهی جورند"},"find":["#number"]},{"t":{"en":"Why this company","tr":"Neden bu şirket","fa":"چرا این شرکت"},"find":["your company","your team","join you","join your","because you"]},{"t":{"en":"A request for an interview","tr":"Mülakat isteği","fa":"درخواست مصاحبه"},"find":["interview","discuss the role","meet you","talk to you","hear from you"]}]},"exit":{"id":"c-int-10-x","course":"interview","unit":"int-10","type":"exit","items":[{"from":"int-10","kind":"mcq","prompt":"Which CV line shows a result?","options":["Grew the shop's online orders by 40% in a year.","Responsible for the shop's website and orders.","Excellent computer skills and a positive attitude."],"correct":0,"point":1,"why":{"en":"'Grew the shop's online orders by 40%' starts with a verb and gives a result. 'Responsible for' names a duty; 'excellent skills' is a claim.","tr":"'Grew the shop's online orders by 40%' fiille başlar ve bir sonuç verir. 'Responsible for' bir görevin adını koyar; 'excellent skills' bir iddiadır.","fa":"«Grew the shop's online orders by 40%» با فعل شروع می‌شود و نتیجه را نشان می‌دهد. responsible for فقط اسم وظیفه است و excellent skills یک ادعاست."}},{"from":"int-10","kind":"blank","prompt":"___ a new filing system in 2023, which saved two hours a week.","options":["Introduced","Introduce","Introduces"],"correct":0,"point":2,"why":{"en":"Introduced: 'in 2023' is finished, so the CV line uses the past simple. 'Introduce' sounds like an order, and 'Introduces' needs a subject.","tr":"Introduced: 'in 2023' bitmiştir, bu yüzden CV satırı past simple kullanır. 'Introduce' emir gibi duyulur; 'Introduces' bir özne ister.","fa":"Introduced درست است، چون in 2023 تمام شده و خط رزومه گذشته‌ی ساده می‌خواهد. Introduce شبیه دستور است و Introduces فاعل لازم دارد."}},{"from":"int-10","kind":"mcq","prompt":"What should the first paragraph of a cover letter say?","options":["The job and where you saw it","Your school and your exam grades","Why you are leaving your job"],"correct":0,"point":1,"why":{"en":"The job and where you saw it: the reader knows at once why you write. School grades come later in the CV, and leaving your job sounds negative.","tr":"İş ve ilanı nerede gördüğün: okuyan neden yazdığını hemen anlar. Okul notları CV'de yer alır; işten ayrılmak olumsuz duyulur.","fa":"خود کار و جایی که آگهی را دیدی؛ خواننده فوراً می‌فهمد چرا می‌نویسی. نمره‌های مدرسه جایشان در رزومه است و حرف از ترک کار منفی است."}},{"from":"int-1","kind":"mcq","prompt":"In \"Tell me about yourself\", what should you say first?","options":["What you do now","Where you were born","Your hobbies and family"],"correct":0,"point":1,"why":{"en":"What you do now: it tells them who you are today. Your birthplace and hobbies don't match the job ad.","tr":"Şimdi ne yaptığın: bugün kim olduğunu söyler. Doğduğun yer ve hobilerin iş ilanıyla eşleşmez.","fa":"کاری که الان می‌کنی؛ می‌گوید امروز کی هستی. محل تولد و سرگرمی‌ها با آگهی شغلی جور نیستند."}},{"from":"int-1","kind":"blank","prompt":"I ___ at the hotel from 2019 to 2022.","options":["worked","have worked","am working"],"correct":0,"point":2,"why":{"en":"worked: 'from 2019 to 2022' is a finished period, so use the past simple. 'Have worked' is for time up to now, and 'am working' is now.","tr":"worked: 'from 2019 to 2022' bitmiş bir dönemdir, bu yüzden past simple. 'Have worked' bugüne kadar olan süre içindir; 'am working' şu anı anlatır.","fa":"worked درست است، چون from 2019 to 2022 دوره‌ی تمام‌شده است و گذشته‌ی ساده می‌خواهد. have worked برای زمانی تا الان است و am working برای همین حالا."}},{"from":"int-1","kind":"mcq","prompt":"What decides what you say in your introduction?","options":["The job ad's top needs","Your full work history","What your friends say"],"correct":0,"point":1,"why":{"en":"The job ad's top needs: you answer what they want. Your full work history is too long, and friends' opinions are not proof.","tr":"İş ilanının en önemli istekleri: onların istediğine cevap verirsin. Tüm iş geçmişin çok uzundur; arkadaşlarının görüşü de kanıt değildir.","fa":"مهم‌ترین نیازهای آگهی؛ این‌طوری به چیزی جواب می‌دهی که آن‌ها می‌خواهند. کل سابقه‌ی کاری خیلی طولانی است و نظر دوستانت هم مدرک نیست."}}]},"explain":{"id":"c-int-10-e","course":"interview","unit":"int-10","type":"explain","level":"B1","title":{"en":"Your CV and cover letter","tr":"CV'n ve ön yazın","fa":"رزومه و کاور لتر تو"},"objective":{"en":"After this lesson, you can write CV lines that show results and a short cover letter for one job ad.","tr":"Bu dersin sonunda sonuç gösteren CV satırları ve tek bir iş ilanı için kısa bir ön yazı yazabileceksin.","fa":"بعد از این درس می‌توانی خط‌هایی برای رزومه بنویسی که نتیجه را نشان می‌دهند و برای یک آگهی شغلی یک کاور لتر کوتاه بنویسی."},"hook":{"en":"An employer reads many CVs for one job, so each line must show what you did and what changed. Start each line with a verb, add a number, and write a cover letter about this job only.","tr":"Bir işveren tek bir iş için çok sayıda CV okur; bu yüzden her satır ne yaptığını ve neyin değiştiğini göstermeli. Her satıra bir fiille başla, bir sayı ekle ve yalnızca bu işle ilgili bir ön yazı yaz.","fa":"کارفرما برای یک کار رزومه‌های زیادی می‌خواند؛ پس هر خط باید نشان بدهد چه کردی و چه چیزی تغییر کرد. هر خط را با فعل شروع کن، یک عدد اضافه کن و کاور لتری بنویس که فقط درباره‌ی همین کار باشد."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Lines that show results, a letter about this job","tr":"Sonuç gösteren satırlar, bu işe özel bir yazı","fa":"خط‌هایی که نتیجه را نشان می‌دهند، نامه‌ای برای همین کار"},"steps":[{"en":"Put lines matching the ad's top three needs first. A busy reader may stop after the top.","tr":"İlanda en çok istenen üç şeye uyan satırları en üste koy. Yoğun bir okuyucu üst kısımdan sonra okumayı bırakabilir.","fa":"خط‌هایی را که با سه نیاز اصلی آگهی جورند اول بیاور، چون خواننده‌ی پرمشغله شاید فقط بالای صفحه را بخواند.","ex":"Ad: English emails, complaints, shift work"},{"en":"Write each line as verb, what you did, then the result. A number makes it believable.","tr":"Her satırı fiil, yaptığın iş ve sonuç olarak yaz. Sayı onu inandırıcı yapar.","fa":"هر خط را این‌طور بنویس: فعل، کاری که کردی و نتیجه. عدد حرفت را باورپذیر می‌کند.","ex":"Answered 70 calls a day, with 92% positive feedback."},{"en":"Skip your photo, birth date and marital status unless asked. They don't show you can do the job.","tr":"İlan istemedikçe fotoğraf, doğum tarihi ve medeni hâl koyma. Bunlar işi yapabileceğini göstermez.","fa":"عکس، تاریخ تولد و وضعیت تأهل را ننویس، مگر اینکه آگهی بخواهد، چون این‌ها نشان نمی‌دهند از پس کار برمی‌آیی.","ex":"Keep: name, phone, email, city. (Marital status = married or single.)"},{"en":"Your cover letter links you to this job: name the job, give two matching facts, ask to meet.","tr":"Ön yazın seni bu işe bağlar: işin adını söyle, uyan iki bilgi ver ve görüşme iste.","fa":"کاور لترت تو را به همین کار وصل می‌کند: اسم کار را بگو، دو واقعیت مرتبط بیاور و درخواست مصاحبه کن.","ex":"Weak: I am applying for any suitable position. Better: I am applying for the Customer Support role you advertised."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"CV lines: verb first, then the result","tr":"CV satırları: önce fiil, sonra sonuç","fa":"خط‌های رزومه: اول فعل، بعد نتیجه"},"steps":[{"en":"Start with the verb and leave out I, because the whole CV is about you.","tr":"Fiille başla ve I yazma, çünkü CV'nin tamamı zaten seninle ilgili.","fa":"خط را با فعل شروع کن و I را ننویس، چون کل رزومه درباره‌ی خودت است.","ex":"Trained 12 new staff."},{"en":"Use the past simple for finished results, and the present simple for duties you still do.","tr":"Bitmiş sonuçlar için past simple, hâlâ yaptığın görevler için present simple kullan.","fa":"برای نتیجه‌ای که تمام شده گذشته‌ی ساده بیاور و برای کاری که هنوز انجام می‌دهی حال ساده.","ex":"Cut costs by 10%. Answer 60 emails a day."},{"en":"Give the size of a change with by + number. Write 20%, not %20.","tr":"Değişimin miktarını by + sayı ile ver. %20 değil, 20% yaz.","fa":"مقدار تغییر را با by و یک عدد بگو، و بنویس 20%، نه %20.","ex":"Increased sales by 20%."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Start with the verb, no I","Trained 12 new staff."],["Finished result: past simple","Cut delivery time by two days."],["A duty you still do: present simple","Answer about 60 emails a day."],["How much: by + number","Increased sales by 20%."],["Numbers in English","20% (not %20), 1,500 (not 1.500)"]]},"tip":{"en":"Turkish writes %20 and 1.500; English writes 20% and 1,500. Turkish and Persian CVs often open lines with 'sorumlu' or 'مسئول'; in English, open with the action.","tr":"Türkçede %20 ve 1.500 yazılır; İngilizcede 20% ve 1,500. Türkçe CV'lerde satırlar çoğu zaman 'sorumlu' ile başlar; İngilizcede yaptığın işle başla: Trained, Cut.","fa":"در انگلیسی علامت درصد بعد از عدد می‌آید (20%) و هزارگان را با ویرگول جدا می‌کنند (1,500). در رزومه‌ی فارسی خیلی از خط‌ها با «مسئول» شروع می‌شوند؛ در انگلیسی خط را با کاری که کردی شروع کن: Trained، Cut."}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"CVs differ by country","tr":"CV ülkeden ülkeye değişir","fa":"رزومه در هر کشور فرق دارد"},"body":{"en":"In the UK it is a CV of up to two pages; in the US, a résumé, often one page. Ask before you name someone as a reference (someone who describes your work).","tr":"Birleşik Krallık'ta CV en fazla iki sayfadır; ABD'de résumé denir ve çoğu zaman tek sayfadır. Birini referans (işini anlatacak kişi) olarak yazmadan önce ona sor.","fa":"در بریتانیا رزومه را CV می‌گویند و معمولاً حداکثر دو صفحه است؛ در آمریکا résumé می‌گویند که اغلب یک صفحه است. قبل از اینکه اسم کسی را به‌عنوان معرف (کسی که کارت را برای کارفرما توضیح می‌دهد) بنویسی، از خودش بپرس."},"phrases":[{"phrase":"In my current role, I...","meaning":{"en":"Starts with what you do now.","tr":"Şu anda ne yaptığınla başlar.","fa":"با کاری که الان می‌کنی شروع می‌کند."}},{"phrase":"As you can see on my CV, ...","meaning":{"en":"Points to a line they can read.","tr":"Okuyabilecekleri bir satırı gösterir.","fa":"به خطی اشاره می‌کند که خودشان می‌توانند بخوانند."}},{"phrase":"The result was...","meaning":{"en":"Brings in your number.","tr":"Sayını devreye sokar.","fa":"عددت را وارد حرفت می‌کند."}},{"phrase":"achievement","meaning":{"en":"Something good you did, with a result.","tr":"başarı; sonucu olan iyi bir iş.","fa":"دستاورد؛ کار خوبی که نتیجه داشته."}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From duty to result","tr":"Görevden sonuca","fa":"از وظیفه به نتیجه"},"item":"Weak: Responsible for customer emails. Hard-working team player. Your facts: about 60 emails a day in English; replies within 4 hours; complaints fell by 20% in a year.","answer":"Answered about 60 customer emails a day in English, within 4 hours. Cut complaints by 20% in one year.","walk":[{"en":"Start with the verb: what did you do?","tr":"Fiille başla: ne yaptın?","fa":"با فعل شروع کن: چه کار کردی؟"},{"en":"Add the numbers from your facts.","tr":"Bilgilerindeki sayıları ekle.","fa":"عددهای واقعیت‌هایت را اضافه کن."},{"en":"Cut words that a reader cannot check.","tr":"Okuyanın kontrol edemeyeceği kelimeleri sil.","fa":"کلمه‌هایی را که خواننده نمی‌تواند بررسی کند حذف کن."}]},"quick":{"prompt":"Increased online orders ___ 35% in one year.","options":["by","with","of"],"correct":0,"why":{"en":"by: by gives the size of a change. 'With' and 'of' don't say how much it grew.","tr":"by: by değişimin miktarını verir. 'With' ve 'of' ne kadar arttığını söylemez.","fa":"جواب by است، چون by مقدار تغییر را نشان می‌دهد؛ with و of نمی‌گویند چقدر بیشتر شد."}},"remember":{"en":"Verb first, then a number, then this job. You can now write CV lines that show results and a cover letter for one job ad. Next, you judge CV lines, talk an interviewer through your CV and write your cover letter.","tr":"Önce fiil, sonra sayı, sonra bu iş. Artık sonuç gösteren CV satırları ve tek bir iş ilanı için bir ön yazı yazabilirsin. Sırada CV satırlarını değerlendirmek, mülakatçıya CV'ni anlatmak ve ön yazını yazmak var.","fa":"اول فعل، بعد عدد، بعد همین کار. حالا می‌توانی خط‌هایی برای رزومه بنویسی که نتیجه را نشان می‌دهند و برای یک آگهی شغلی کاور لتر بنویسی. در ادامه خط‌های رزومه را ارزیابی می‌کنی، رزومه‌ات را برای مصاحبه‌کننده توضیح می‌دهی و کاور لترت را می‌نویسی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"How you did it: by + -ing, from ... to","tr":"Nasıl yaptığın: by + -ing, from ... to","fa":"چطور انجامش دادی: by + ‎-ing و from ... to"},"steps":[{"en":"Say how you did it: by + -ing.","tr":"Nasıl yaptığını söyle: by + -ing.","fa":"برای اینکه بگویی چطور انجامش دادی، by و فعل ing‌دار بیاور.","ex":"Cut costs by switching suppliers."},{"en":"Put how first when it is the strong part: By + -ing, then the result.","tr":"Güçlü kısım yöntemse onu başa al: By + -ing, sonra sonuç.","fa":"اگر نقطه‌ی قوت همان روش است، اول بیاورش: By + ‎-ing و بعد نتیجه.","ex":"By introducing online booking, cut calls by 30%."},{"en":"Show the change with from ... to.","tr":"Değişimi from ... to ile göster.","fa":"تغییر را با from ... to نشان بده.","ex":"Reduced delivery time from five days to two."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["How: by + -ing","Cut costs by switching suppliers."],["How first, for focus","By introducing online booking, cut calls by 30%."],["The change: from ... to ...","Reduced delivery time from five days to two."]]},"body":{"en":"B2: in your writing, add one line that says how, with by + -ing, or shows a change with from ... to.","tr":"B2: yazına, nasıl yaptığını by + -ing ile anlatan ya da from ... to ile bir değişimi gösteren bir satır ekle.","fa":"در مسیر B2: در نوشته‌ات یک خط اضافه کن که با by + ‎-ing بگوید چطور انجامش دادی، یا با from ... to تغییر را نشان بدهد."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
